using IAM.Infrastructure.Data.Entities;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using System.Security.Claims;
namespace IAMService.Controllers;
public record PartnerRequestDto(string Title,string Content,decimal? Price,TimeOnly? OpeningTime,TimeOnly? ClosingTime,string Location,decimal? Latitude,decimal? Longitude);
[ApiController][Authorize(Roles="Partner")][Route("api/partner/requests")]
public class PartnerRequestController(IAMDbContext db,IWebHostEnvironment env):ControllerBase {
 Guid Uid=>Guid.Parse(User.FindFirstValue(ClaimTypes.NameIdentifier)!);
 async Task<PartnerProfile?> Profile()=>await db.PartnerProfiles.FirstOrDefaultAsync(p=>p.UserId==Uid);
 [HttpGet]public async Task<IActionResult> List(){var p=await Profile();return p==null?NotFound():Ok(await db.PartnerContentRequests.AsNoTracking().Include(x=>x.Images).Where(x=>x.PartnerId==p.Id).OrderByDescending(x=>x.CreatedAt).ToListAsync());}
 [HttpGet("{id:guid}")]public async Task<IActionResult> Get(Guid id){var p=await Profile();if(p==null)return NotFound();var r=await db.PartnerContentRequests.AsNoTracking().Include(x=>x.Images).FirstOrDefaultAsync(x=>x.Id==id&&x.PartnerId==p.Id);return r==null?NotFound():Ok(r);}
 [HttpPost]public async Task<IActionResult> Create(PartnerRequestDto x){var p=await Profile();if(p==null||p.Status!="Active")return Forbid();if(string.IsNullOrWhiteSpace(x.Title)||x.Price<0)return BadRequest();var r=new PartnerContentRequest{PartnerId=p.Id,Title=x.Title,Content=x.Content,Price=x.Price,OpeningTime=x.OpeningTime,ClosingTime=x.ClosingTime,Location=x.Location,Latitude=x.Latitude,Longitude=x.Longitude};db.PartnerContentRequests.Add(r);await db.SaveChangesAsync();return Ok(new{r.Id,r.Status});}
 [HttpPut("{id:guid}")]public async Task<IActionResult> Update(Guid id,PartnerRequestDto x){var p=await Profile();if(p==null)return NotFound();var r=await db.PartnerContentRequests.FirstOrDefaultAsync(r=>r.Id==id&&r.PartnerId==p.Id);if(r==null)return NotFound();if(r.Status!="Draft")return Conflict("Only drafts can be edited");if(x.Price<0)return BadRequest();r.Title=x.Title;r.Content=x.Content;r.Price=x.Price;r.OpeningTime=x.OpeningTime;r.ClosingTime=x.ClosingTime;r.Location=x.Location;r.Latitude=x.Latitude;r.Longitude=x.Longitude;r.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();return NoContent();}
 [HttpPost("{id:guid}/submit")]public async Task<IActionResult> Submit(Guid id){var p=await Profile();if(p==null)return NotFound();var r=await db.PartnerContentRequests.FirstOrDefaultAsync(r=>r.Id==id&&r.PartnerId==p.Id);if(r==null)return NotFound();if(r.Status!="Draft")return Conflict();r.Status="Pending";r.UpdatedAt=DateTime.UtcNow;await db.SaveChangesAsync();return Ok(new{r.Status});}
 [HttpPost("{id:guid}/images")][RequestSizeLimit(10_000_000)]public async Task<IActionResult> Upload(Guid id,IFormFile file){var p=await Profile();if(p==null)return NotFound();var r=await db.PartnerContentRequests.FirstOrDefaultAsync(r=>r.Id==id&&r.PartnerId==p.Id);if(r==null)return NotFound();if(r.Status!="Draft")return Conflict();if(file==null||file.Length==0||file.Length>5_000_000)return BadRequest("Image must be 1-5 MB");var ext=Path.GetExtension(file.FileName).ToLowerInvariant();if(ext is not (".jpg" or ".jpeg" or ".png" or ".webp"))return BadRequest("Unsupported image");using var s=file.OpenReadStream();var header=new byte[12];var n=await s.ReadAsync(header);var valid=(ext is ".jpg" or ".jpeg")&&n>=3&&header[0]==255&&header[1]==216&&header[2]==255||(ext==".png"&&n>=8&&header.AsSpan(0,8).SequenceEqual(new byte[]{137,80,78,71,13,10,26,10}))||(ext==".webp"&&n>=12&&System.Text.Encoding.ASCII.GetString(header,0,4)=="RIFF"&&System.Text.Encoding.ASCII.GetString(header,8,4)=="WEBP");if(!valid)return BadRequest("Invalid image content");s.Position=0;var folder=Path.Combine(env.ContentRootPath,"uploads","partner-requests");Directory.CreateDirectory(folder);var name=Guid.NewGuid().ToString("N")+ext;var path=Path.Combine(folder,name);await using(var dest=System.IO.File.Create(path))await s.CopyToAsync(dest);var img=new PartnerRequestImage{RequestId=id,ImageUrl="/api/partner/requests/images/"+name};db.PartnerRequestImages.Add(img);await db.SaveChangesAsync();return Ok(new{img.Id,img.ImageUrl});}
 [AllowAnonymous][HttpGet("images/{name}")]public IActionResult Image(string name){if(name!=Path.GetFileName(name))return BadRequest();var path=Path.Combine(env.ContentRootPath,"uploads","partner-requests",name);if(!System.IO.File.Exists(path))return NotFound();return PhysicalFile(path,name.EndsWith(".png")?"image/png":name.EndsWith(".webp")?"image/webp":"image/jpeg");}
 [HttpDelete("{id:guid}/images/{imageId:guid}")]public async Task<IActionResult> DeleteImage(Guid id,Guid imageId){var p=await Profile();if(p==null)return NotFound();var r=await db.PartnerContentRequests.FirstOrDefaultAsync(r=>r.Id==id&&r.PartnerId==p.Id);if(r==null)return NotFound();if(r.Status!="Draft")return Conflict();var img=await db.PartnerRequestImages.FirstOrDefaultAsync(i=>i.Id==imageId&&i.RequestId==id);if(img==null)return NotFound();db.PartnerRequestImages.Remove(img);await db.SaveChangesAsync();var name=Path.GetFileName(img.ImageUrl);var path=Path.Combine(env.ContentRootPath,"uploads","partner-requests",name);if(System.IO.File.Exists(path))System.IO.File.Delete(path);return NoContent();}
}
